import DataService from '../../service/DataService'

let buttons =
    [
        {
            title: 'Add Purchase Request',
            iconClass: 'fa fa-plus',
            callbackfunction: 'RequestNewProductType',
            href: '',
            additionalClass: '',
            id: 'RequestNewProductType',
            isdisabled: false,
            isvisible: true,
            checkPrivilege: false
        },
        {
            title: 'Delete',
            id: 'DeleteMultiple',
            iconClass: 'fa fa-trash',
            callbackfunction: 'deleteItem',
            additionalClass: '',
            isdisabled: true,
            isvisible: true,
            checkPrivilege: true,
            isEnabledOnSelectedRow: true
        },

    ];


let leftsearchSchema = [
    {
        fieldName: "ProductName",
        fieldType: "text",
        fieldIcon: "fa-file",
        paramName: "search",
        fieldSearchConditionName: [''],
        isSearch: false,
        value: "",
        listOptions: []
    },
    {

        fieldName: 'ProductType',
        fieldType: "ddl-check",
        fieldIcon: "fa-user",
        paramName: "assettypeid",
        fieldSearchConditionName: [''],
        isSearch: false,
        value: "",
        listOptions: []
    }

]

function bindleftCommonSearchdropdown(instance, modulename, filtername) {
    var vm = instance;
    let productTypeData = [];
    if (filtername == "Product Type") {
        vm.isLoading = true;
        var url = `type=ITEMCODE&issueTo=&locationId=`;
        DataService.GetAssetTypeCustom(url).then(response => {

            if (response.data !== null) {

                let obj = {}

                JSON.parse(response.data).forEach(item => {
                    obj = {
                        name: item.ASSETTYPE,
                        value: `${item.ASSETID}`
                    }
                    productTypeData.push(obj);
                });
                vm.leftSearchFields[1].listOptions = productTypeData;
            }
        })
    }
}
export default { buttons, leftsearchSchema, bindleftCommonSearchdropdown };